public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("The file must not be null");
    }

    // Schedule the file or directory for deletion on JVM exit
    file.deleteOnExit();

    // If the file is a directory, ensure all its contents are also deleted on JVM exit
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File f : files) {
                forceDeleteOnExit(f);
            }
        }
    }
