    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and resultMap cannot be null");
    }

    Set<V> partitionA = new HashSet<>();
    Set<V> partitionB = new HashSet<>();

    // Assuming resultMap contains vertices for both partitions
    for (V vertex : resultMap.values()) {
        if (partitionA.size() < resultMap.size() / 2) {
            partitionA.add(vertex);
        } else {
            partitionB.add(vertex);
        }
    }

    // Add edges between all vertices in partitionA and partitionB
    for (V vertexA : partitionA) {
        for (V vertexB : partitionB) {
            target.addEdge(vertexA, vertexB);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Graph and resultMap cannot be null");
    }

    Set<V> leftPartition = new HashSet<>();
    Set<V> rightPartition = new HashSet<>();

    // Assuming resultMap entries are split into two groups for bipartition
    // For simplicity, let's assume keys starting with "L" are in the left partition and "R" in the right
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        if (entry.getKey().startsWith("L")) {
            leftPartition.add(entry.getValue());
        } else if (entry.getKey().startsWith("R")) {
            rightPartition.add(entry.getValue());
        } else {
            throw new IllegalArgumentException("Vertex key must start with 'L' or 'R' to denote partition");
        }
    }

    // Add vertices to the graph
    for (V vertex : leftPartition) {
        target.addVertex(vertex);
    }
    for (V vertex : rightPartition) {
        target.addVertex(vertex);
    }

    // Connect each vertex in the left partition to each vertex in the right partition
    for (V leftVertex : leftPartition) {
        for (V rightVertex : rightPartition) {
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Graph and resultMap cannot be null");
    }

    Collection<V> vertices = resultMap.values();
    int size = vertices.size();
    if (size < 2) {
        throw new IllegalArgumentException("At least two vertices are required to form a bipartite graph");
    }

    List<V> list = new ArrayList<>(vertices);
    int mid = size / 2;

    for (int i = 0; i < mid; i++) {
        for (int j = mid; j < size; j++) {
            target.addEdge(list.get(i), list.get(j));
        }
    }
}

