public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Arguments cannot be null");
    }
    try {
        // Compute the size of the message
        int size = schema.getSerializedSize(message, buffer);

        // Write the size of the message as a varint
        LinkedBuffer varintBuffer = LinkedBuffer.allocate(5);
        ProtobufOutput varintOutput = new ProtobufOutput(varintBuffer);
        varintOutput.writeRawVarInt32(size);
        varintOutput.flush();
        out.write(varintBuffer.buffer, 0, varintOutput.getTotalBytesWritten());

        // Write the message itself
        ProtobufOutput output = new ProtobufOutput(buffer);
        schema.writeTo(output, message);
        output.flush();
        out.write(buffer.buffer, 0, output.getTotalBytesWritten());

        return size;
    } catch (IOException e) {
        throw e;
    } catch (Exception e) {
        throw new IOException("Error serializing message", e);
    } finally {
        buffer.clear();
    }
}

