public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new NullPointerException("Message cannot be null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new NullPointerException("LinkedBuffer cannot be null");
    }

    final byte[] bytes;
    try {
        bytes = schema.toByteArray(message, buffer);
    } finally {
        buffer.clear();
    }

    final int size = bytes.length;
    writeRawVarint32(out, size);
    out.write(bytes);
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    // Serialize the message into a byte array
    byte[] bytes = schema.writeTo(buffer, message);

    // Prefix the byte array with its length
    int length = bytes.length;
    out.write(length >>> 24);
    out.write(length >>> 16);
    out.write(length >>> 8);
    out.write(length);

    // Write the serialized message to the OutputStream
    out.write(bytes);

    // Return the size of the message
    return length;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("OutputStream, message, schema, and buffer cannot be null");
    }
    try {
        // Calculate the size of the message
        int size = schema.getSerializedSize(message, buffer);

        // Write the size as a varint to the output stream
        LinkedBuffer varintBuffer = new LinkedBuffer(5); // 5 bytes is sufficient to encode any integer as a varint
        int varintSize = ProtostuffioUtil.writeVarInt32(size, out, varintBuffer);

        // Write the message to the output stream
        schema.writeTo(out, message, buffer);

        // Total size is the size of the varint + the size of the message
        return varintSize + size;
    } catch (Exception e) {
        throw new IOException("Error writing message to OutputStream", e);
    } finally {
        buffer.clear();
    }
}

