public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Index and length must be non-negative and the sum of index and length must not exceed the string length");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;
        } else if (ch < 0x800) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len) {
                char nextChar = str.charAt(i + 1);
                if (Character.isLowSurrogate(nextChar)) {
                    i++; // Skip the low surrogate as it is part of the current code point
                    size += 4; // 4 bytes for a surrogate pair
                    continue;
                }
            }
            throw new IllegalArgumentException("Invalid high surrogate character without a following low surrogate");
        } else {
            size += 3;
        }
    }
    return size;
}

