public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    try {
        int length = str.length();
        int offset = 0;
        while (offset < length) {
            char c = str.charAt(offset++);
            if (c < 0x80) {
                lb = lb.buffer(*lb.offset++) = (byte) c;
            } else if (c < 0x800) {
                lb = lb.buffer(*lb.offset++) = (byte) (0xc0 | (c >> 6));
                lb = lb.buffer(*lb.offset++) = (byte) (0x80 | (c & 0x3f));
            } else if (c >= 0xD800 && c <= 0xDFFF) {
                if (offset < length) {
                    char c2 = str.charAt(offset++);
                    if (c >= 0xDC00 && c <= 0xDFFF) {
                        throw new IllegalArgumentException("Unpaired surrogate in string");
                    }
                    if (c2 < 0xDC00 || c2 > 0xDFFF) {
                        throw new IllegalArgumentException("Unpaired surrogate in string");
                    }
                    int codePoint = ((c & 0x3FF) << 10) + (c2 & 0x3FF) + 0x10000;
                    lb = lb.buffer(*lb.offset++) = (byte) (0xf0 | (codePoint >> 18));
                    lb = lb.buffer(*lb.offset++) = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
                    lb = lb.buffer(*lb.offset++) = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
                    lb = lb.buffer(*lb.offset++) = (byte) (0x80 | (codePoint & 0x3f));
                } else {
                    throw new IllegalArgumentException("Unpaired surrogate in string");
                }
            } else {
