    }

    String value = props.getProperty(key);
    if (value == null) {
        return null; // or throw an exception if not found is an error case
    }

    // Simple variable substitution logic assuming ${var} format
    while (value.contains("${")) {
        int start = value.indexOf("${");
        int end = value.indexOf("}", start);
        if (end == -1) {
            break; // malformed variable, stop processing
        }
        String varName = value.substring(start + 2, end);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            value = value.substring(0, start) + varValue + value.substring(end + 1);
        } else {
            value = value.substring(0, start) + value.substring(end + 1); // remove if not found
        }
    }

    return value;
}

