private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // Descriptor is a method descriptor, skip to the argument types
        index = descriptor.indexOf(')') + 1;
        if (index <= 1) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
    }

    while (index < descriptor.length()) {
        char c = descriptor.charAt(index++);
        switch (c) {
            case 'B':
            case 'C':
            case 'I':
            case 'S':
            case 'Z':
                // These types occupy one slot in the frame stack
                break;
            case 'F':
                // Float also occupies one slot in the frame stack
                break;
            case 'D':
            case 'J':
                // Double and long occupy two slots in the frame stack
                break;
            case 'L':
            case '[':
                // Reference types (objects and arrays) occupy one slot in the frame stack
                while (index < descriptor.length() && descriptor.charAt(index) != ';') {
                    index++;
                }
                break;
            default:
                throw new IllegalArgumentException("Unknown type character in descriptor: " + c);
        }
    }
}

