protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        throw new IllegalArgumentException("Tour must contain at least one edge");
    }

    List<V> vertexList = new ArrayList<>();
    Map<V, List<E>> vertexEdgeMap = new HashMap<>();

    // Populate vertexEdgeMap with edges connected to each vertex
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        vertexEdgeMap.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        vertexEdgeMap.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
    }

    // Find a starting vertex with an odd degree
    V startVertex = null;
    for (Map.Entry<V, List<E>> entry : vertexEdgeMap.entrySet()) {
        if (entry.getValue().size() % 2 != 0) {
            startVertex = entry.getKey();
            break;
        }
    }

    // If no vertex with an odd degree is found, use any vertex
    if (startVertex == null) {
        startVertex = graph.getEdgeSource(edgeList.get(0));
    }

    // Hierholzer's algorithm to find Eulerian circuit
    Deque<E> stack = new ArrayDeque<>();
    List<E> circuit = new ArrayList<>();
    stack.push(edgeList.get(0));
    vertexList.add(startVertex);

    while (!stack.isEmpty()) {
        V currentVertex = stack.peek();
        List<E> edges = vertexEdgeMap.get(currentVertex);

        if (edges != null && !edges.isEmpty()) {
            E edge = edges.remove(edges.size() - 1);
            stack.push(edge);
            V nextVertex = graph.getEdgeSource(edge).equals(currentVertex) ? graph.getEdgeTarget(edge) : graph.getEdgeSource(edge);
            vertexList.add(nextVertex);
        } else {
            circuit.add(stack.pop());
        }
    }

    // Reverse circuit to get the correct order
    Collections.reverse(circuit);

    // Create and return the graph path
    return new GraphPathImpl<>(graph, vertexList, circuit, 0.0);
}

