protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    Map<V, List<E>> adjacencyList = new HashMap<>();
    for (E edge : graph.edgeSet()) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        adjacencyList.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        if (!graph.getType().isDirected()) {
            adjacencyList.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
        }
    }

    List<E> pathEdges = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();
    V startVertex = graph.getEdgeSource(tour.iterator().next());
    Deque<V> stack = new ArrayDeque<>();
    stack.push(startVertex);

    while (!stack.isEmpty() && pathEdges.size() < tour.size()) {
        V current = stack.peek();
        boolean foundUnvisitedEdge = false;
        for (E edge : adjacencyList.getOrDefault(current, Collections.emptyList())) {
            if (!visitedEdges.contains(edge) && tour.contains(edge)) {
                visitedEdges.add(edge);
                pathEdges.add(edge);
                V nextVertex = graph.getEdgeTarget(edge);
                if (nextVertex.equals(current)) {
                    nextVertex = graph.getEdgeSource(edge);
                }
                stack.push(nextVertex);
                foundUnvisitedEdge = true;
                break;
            }
        }
        if (!foundUnvisitedEdge) {
            stack.pop();
        }
    }

    if (pathEdges.size() != tour.size()) {
        throw new IllegalArgumentException("The provided set of edges does not form a valid tour in the graph");
    }

    List<V> vertexPath = new ArrayList<>();
    for (E edge : pathEdges) {
        if (vertexPath.isEmpty() || !vertexPath.get(vertexPath.size() - 1).equals(graph.getEdgeSource(edge))) {
            vertexPath.add(graph.getEdgeSource(edge));
        }
        vertexPath.add(graph.getEdgeTarget(edge));
    }

    double weight = pathEdges.stream().mapToDouble(graph::getEdgeWeight).sum();

    return new GraphPathImpl<>(graph, startVertex, vertexPath, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    List<V> pathVertices = new ArrayList<>();
    Set<E> usedEdges = new HashSet<>();
    V startVertex = null;

    // Find a starting vertex
    for (E edge : tour) {
        startVertex = graph.getEdgeSource(edge);
        break;
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("Tour set is empty or invalid");
    }

    V currentVertex = startVertex;
    pathVertices.add(currentVertex);

    while (tour.size() > usedEdges.size()) {
        E outgoingEdge = null;
        for (E edge : tour) {
            if (!usedEdges.contains(edge)) {
                if (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex)) {
                    outgoingEdge = edge;
                    break;
                }
            }
        }

        if (outgoingEdge == null) {
            throw new IllegalArgumentException("Tour set does not form a valid path in the graph");
        }

        usedEdges.add(outgoingEdge);
        V nextVertex = graph.getEdgeTarget(outgoingEdge).equals(currentVertex) ? graph.getEdgeSource(outgoingEdge) : graph.getEdgeTarget(outgoingEdge);
        pathVertices.add(nextVertex);
        currentVertex = nextVertex;
    }

    return new GraphPathImpl<>(graph, startVertex, currentVertex, pathVertices, usedEdges.stream().map(graph::getEdgeWeight).reduce(0.0, Double::sum));
}

