private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null) {
        throw new IllegalArgumentException("The provided list cannot be null.");
    }

    ListNode<E> current = list.head;
    while (current != null) {
        ListNode<E> next = current.next;
        list.removeListNode(current);
        this.addListNode(current);
        current = next;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("The list to move nodes from cannot be null.");
    }

    ListNode<E> current = list.head;
    while (current != null) {
        ListNode<E> nextNode = current.next;

        // Remove the node from the original list
        if (current.prev != null) {
            current.prev.next = current.next;
        } else {
            list.head = current.next;
        }
        if (current.next != null) {
            current.next.prev = current.prev;
        } else {
            list.tail = current.prev;
        }

        // Add the node to this list
        if (this.head == null) {
            this.head = this.tail = current;
            current.prev = current.next = null;
        } else {
            this.tail.next = current;
            current.prev = this.tail;
            current.next = null;
            this.tail = current;
        }

        current = nextNode;
    }

    // Clear the original list
    list.head = list.tail = null;
}

