    }

    // Assuming we want to abbreviate the name by taking the first character and the last character
    // and the characters between nameStart and the end of the buffer.
    if (nameStart == buf.length() - 1) {
        // If nameStart is the last character, we just append that character
        buf.append(buf.charAt(nameStart));
    } else {
        // Otherwise, append the first character, the character at nameStart, and the last character
        char firstChar = buf.charAt(0);
        char startChar = buf.charAt(nameStart);
