        }
        if (nameStart < 0 || nameStart >= buf.length()) {
            throw new IndexOutOfBoundsException("nameStart is out of bounds");
        }
        String name = buf.substring(nameStart);
        String[] parts = name.split(" ");
        if (parts.length > 1) {
            StringBuilder abbreviation = new StringBuilder();
            for (int i = 0; i < parts.length - 1; i++) {
                if (!parts[i].isEmpty()) {
                    abbreviation.append(parts[i].charAt(0)).append(". ");
                }
            }
            abbreviation.append(parts[parts.length - 1]);
            buf.replace(nameStart, buf.length(), abbreviation.toString());
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}

