        if (descriptor.charAt(0) == '(') {
            // It's a method descriptor, extract argument types
            int index = 1;
            while (descriptor.charAt(index) != ')') {
                index = popType(descriptor, index);
            }
        } else {
            // It's a field descriptor, pop the type
            popType(descriptor, 0);
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        if (descriptor.startsWith("(")) {
            // It's a method descriptor, find the argument types
            int end = descriptor.indexOf(')');
            if (end == -1) {
                throw new IllegalArgumentException("Invalid method descriptor");
            }
            String argumentTypes = descriptor.substring(1, end);
            int index = 0;
            while (index < argumentTypes.length()) {
                char c = argumentTypes.charAt(index);
                switch (c) {
                    case 'B': case 'C': case 'D': case 'F': case 'I': case 'J': case 'S': case 'Z':
                        // Pop one slot for each of these types
                        index++;
                        break;
                    case 'L':
                        // Pop one slot for object reference
                        index = argumentTypes.indexOf(';', index) + 1;
                        if (index == 0) {
                            throw new IllegalArgumentException("Invalid object reference in descriptor");
                        }
                        break;
                    case '[':
                        // Pop one slot for array reference
                        int arrayDim = 1;
                        while (index + arrayDim < argumentTypes.length() && argumentTypes.charAt(index + arrayDim) == '[') {
                            arrayDim++;
                        }
                        if (index + arrayDim == argumentTypes.length()) {
                            throw new IllegalArgumentException("Invalid array descriptor");
                        }
                        char arrayType = argumentTypes.charAt(index + arrayDim);
                        if (arrayType == 'L') {
                            index = argumentTypes.indexOf(';', index + arrayDim) + 1;
                        } else {
                            index = index + arrayDim + 1;
                        }
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid type character in descriptor: " + c);
                }
            }
        } else {
            // It's a field descriptor, pop based on the type
            switch (descriptor.charAt(0)) {
                case 'B': case 'C': case 'D': case 'F': case 'I': case 'J': case 'S': case 'Z':
                    // Pop one slot for each of these types
                    break;
                case 'L':
                    // Pop one slot for object reference
                    if (descriptor.indexOf(';') == -1) {
                        throw new IllegalArgumentException("Invalid object reference in descriptor");
                    }
                    break;
                case '[':
                    // Pop one slot for array reference
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type character in descriptor: " + descriptor.charAt(0));
            }
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

private void pop(final String descriptor){
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // Check if the descriptor is a method descriptor
    if (descriptor.startsWith("(")) {
        int end = descriptor.indexOf(')');
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
        String argumentTypes = descriptor.substring(1, end);
        for (int i = 0; i < argumentTypes.length(); ) {
            char c = argumentTypes.charAt(i);
            switch (c) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'S': // short
                case 'Z': // boolean
                    i++;
                    break;
                case 'J': // long (double wide)
                    i += 2;
                    break;
                case 'L': // object
                case '[': // array
                    int semi = argumentTypes.indexOf(';', i);
                    if (semi == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: missing ';' after object/array type");
                    }
                    i = semi + 1;
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor character: " + c);
            }
        }
    } else {
        // Treat the descriptor as a field descriptor
        switch (descriptor.charAt(0)) {
            case 'B':
            case 'C':
            case 'D':
            case 'F':
            case 'I':
            case 'S':
            case 'Z':
                break;
            case 'J':
                break; // Long is double wide
            case 'L':
            case '[':
                if (descriptor.indexOf(';') == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' after object/array type");
                }
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor for field: " + descriptor);
        }
    }
}

