}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non-null.");
    }

    // Normalize the path by ensuring it ends with a "/"
    if (!path.endsWith("/")) {
        path += "/";
    }

    // Tokenize the relative path
    String[] tokens = relativePath.split("/");

    // Process each token
    for (String token : tokens) {
        if (token.equals(".")) {
            // Current directory, do nothing
            continue;
        } else if (token.equals("..")) {
            // Parent directory, remove last directory from the path
            int lastSlashIndex = path.lastIndexOf("/");
            if (lastSlashIndex != -1 && lastSlashIndex != 0) {
                path = path.substring(0, lastSlashIndex);
            }
        } else if (!token.isEmpty()) {
            // Regular directory or file name, append to the path
            path += token + "/";
        }
    }

    // Remove trailing slash if it exists and it's not the root
    if (path.length() > 1 && path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }

    return path;
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non-null");
    }

    // Normalize the paths by removing trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Process the relative path components
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (pathComponents.length > 0) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else if (!component.equals(".")) {
            // Add non-empty and non "." components to the path
            String[] newPathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            newPathComponents[newPathComponents.length - 1] = component;
            pathComponents = newPathComponents;
        }
    }

    // Build the final path
    return String.join("/", pathComponents);
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the paths to handle any duplicate slashes or trailing slashes
    path = path.replace("\\", "/").replaceAll("/+", "/").replaceAll("/$", "");
    relativePath = relativePath.replace("\\", "/").replaceAll("/+", "/");

    // Handle the case where relativePath is absolute
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Apply the relative path components
    for (String component : relativePathComponents) {
        if (component.equals(".")) {
            // Stay in the same directory
            continue;
        } else if (component.equals("..")) {
            // Go up one directory
            if (pathComponents.length > 0) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else {
            // Go into a subdirectory
            String[] newPathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            newPathComponents[newPathComponents.length - 1] = component;
            pathComponents = newPathComponents;
        }
    }

    // Reassemble the path
    return String.join("/", pathComponents);
}

