    }

    // Normalize the input paths by removing any trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the relative path into components
    String[] relativeParts = relativePath.split("/");
    StringBuilder resultPath = new StringBuilder(path);

    for (String part : relativeParts) {
        if (part.equals("..")) {
            // Move up one directory if possible
            int lastSlashIndex = resultPath.lastIndexOf("/");
            if (lastSlashIndex != -1) {
                resultPath.setLength(lastSlashIndex);
            }
        } else if (!part.equals(".")) {
            // Append the directory or file name
            resultPath.append("/").append(part);
        }
    }

    return resultPath.toString();
}

